import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:share_plus/share_plus.dart';import '../../../core/providers/app_providers.dart';import '../../../shared/widgets/disclaimer_card.dart';import '../../care/presentation/calendar_screen.dart';import '../../records/presentation/records_screen.dart';import '../../feeding/presentation/feeding_screen.dart';import '../../activity/presentation/activity_screen.dart';import '../../checklists/presentation/checklists_screen.dart';import '../../sharing/presentation/sitter_handoff_screen.dart';import '../../contacts/presentation/emergency_screen.dart';
class SettingsScreen extends ConsumerWidget{const SettingsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider);return ListView(padding:const EdgeInsets.all(18),children:[Text('Settings',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:14),const DisclaimerCard('Pet profiles, reminders, records and preferences are stored on this device. No account, cloud sync or personal-data upload.'),const SizedBox(height:14),Card(child:Column(children:[ListTile(leading:const Icon(Icons.straighten),title:const Text('Weight units'),subtitle:Text(c.weightUnit),onTap:()async{final v=await _choose(context,'Weight units',['lb','kg']);if(v!=null)c.saveUnits(weight:v);}),ListTile(leading:const Icon(Icons.route),title:const Text('Distance units'),subtitle:Text(c.distanceUnit),onTap:()async{final v=await _choose(context,'Distance units',['mi','km']);if(v!=null)c.saveUnits(distance:v);}),ListTile(leading:const Icon(Icons.thermostat),title:const Text('Temperature units'),subtitle:Text(c.temperatureUnit),onTap:()async{final v=await _choose(context,'Temperature units',['°F','°C']);if(v!=null)c.saveUnits(temperature:v);}),const Divider(height:1),ListTile(leading:const Icon(Icons.event),title:const Text('Calendar agenda'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const CalendarScreen()))),ListTile(leading:const Icon(Icons.folder_copy_outlined),title:const Text('Health records'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const RecordsScreen()))),ListTile(leading:const Icon(Icons.restaurant),title:const Text('Feeding journal'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const FeedingScreen()))),ListTile(leading:const Icon(Icons.directions_walk),title:const Text('Activity journal'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ActivityScreen()))),ListTile(leading:const Icon(Icons.checklist),title:const Text('Care checklists'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ChecklistsScreen()))),ListTile(leading:const Icon(Icons.contact_phone),title:const Text('Vet & emergency contacts'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const EmergencyScreen()))),ListTile(leading:const Icon(Icons.ios_share),title:const Text('Pet-sitter handoff'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const SitterHandoffScreen()))),const Divider(height:1),ListTile(leading:const Icon(Icons.file_download_outlined),title:const Text('Export local data'),subtitle:const Text('Create a versioned JSON backup'),onTap:()async{final text=await c.exportData();if(context.mounted)await SharePlus.instance.share(ShareParams(text:text,subject:'PawPal local data backup'));}),ListTile(leading:const Icon(Icons.cloud_sync_outlined),title:const Text('Content updates'),subtitle:const Text('Read-only public editorial updates; no pet data is uploaded'),onTap:()=>showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('Editorial content updates'),content:const Text('The GitHub content source is not configured in this build. Bundled starter content remains available; personal data is never sent to GitHub.'),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Close'))]))),const ListTile(leading:Icon(Icons.light_mode_outlined),title:Text('Appearance'),subtitle:Text('PawPal uses a light-only appearance.')),const ListTile(leading:Icon(Icons.privacy_tip_outlined),title:Text('Privacy'),subtitle:Text('No account, backend, Firebase or cloud sync.'))]))]);}}
Future<String?> _choose(BuildContext context,String title,List<String> options)=>showDialog<String>(context:context,builder:(d)=>SimpleDialog(title:Text(title),children:options.map((v)=>SimpleDialogOption(onPressed:()=>Navigator.pop(d,v),child:Text(v))).toList()));
